    ("掃除機", "そうじき"), ("運動靴", "うんどうぐつ"), ("学生証", "がくせいしょう"),
    ("保険証", "ほけんしょう"), ("予約", "よやく"), ("準備", "じゅんび"),
    ("練習", "れんしゅう"), ("試合", "しあい"), ("経験", "けいけん"),
    ("習慣", "しゅうかん"), ("健康", "けんこう"), ("相談", "そうだん"),
    ("案内", "あんない"), ("説明", "せつめい"), ("紹介", "しょうかい"),
    ("連絡", "れんらく"), ("約束", "やくそく"), ("故障", "こしょう"),
    ("事故", "じこ"), ("怪我", "けが"), ("心配", "しんぱい"),
    ("丁寧", "ていねい"), ("熱心", "ねっしん"), ("複雑", "ふくざつ"),
    ("簡単", "かんたん"), ("便利", "べんり"), ("不便", "ふべん"),
    ("特別", "とくべつ"), ("大切", "たいせつ"), ("必要", "ひつよう"),
    ("無料", "むりょう"), ("値段", "ねだん"), ("料金", "りょうきん"),
    ("辞書", "じしょ"), ("雑誌", "ざっし"), ("新聞", "しんぶん"),
    ("手紙", "てがみ"), ("切手", "きって"), ("手袋", "てぶくろ"),
    ("時計", "とけい"), ("荷物", "にもつ"), ("階段", "かいだん"),
