CONTEXT_BADGES = [
    "【高校生活・放課後】",
    "【修学旅行・京都案内】",
    "【日本留学・ホームステイ】",
    "【書店・カフェアルバイト】",
    "【市民図書館・自習室】",
    "【部活動・大会準備】",
    "【健康管理・食生活】",
    "【地域の国際交流】",
]


def inject_inline_ruby(stem: str, category: str) -> str:
    if category == "KANJI" or "<ruby>" in stem:
        return stem
    import re
    parts = re.split(r"(<u>.*?</u>|<[^>]+>)", stem)
    for idx, part in enumerate(parts):
        if part.startswith("<"):
            continue
        for kj, rd in COMMON_N4_RUBY:
            if kj in part and f"<ruby>{kj}" not in part:
                part = part.replace(kj, f"<ruby>{kj}<rt>{rd}</rt></ruby>", 1)
        parts[idx] = part
    return "".join(parts)


def rotate_options(q: dict, shift: int) -> dict:
    if q.get("category") == "STAR":
        return q
    opts = q.get("options", [])
    exps = q.get("optionExplanations", [])
    if len(opts) != 4 or len(exps) != 4:
        return q
    s = shift % 4
    if s == 0:
        return q
    cidx = q["correctIndex"]
    pairs = [(opts[i], exps[i], i == cidx) for i in range(4)]
    rotated = pairs[s:] + pairs[:s]
    q["options"] = [p[0] for p in rotated]
    q["optionExplanations"] = [p[1] for p in rotated]
    q["correctIndex"] = next(i for i, p in enumerate(rotated) if p[2])
    return q


def build_n4_bank() -> list[dict]:
    bloom_map = {
        "KANJI": ("L1_REMEMBER", "L1 記憶・漢字讀音與表記提取"),
        "VOCAB": ("L2_UNDERSTAND", "L2 理解・語境詞彙與用法辨析"),
        "GRAMMAR": ("L3_APPLY", "L3 應用・N4核心文法與句型接續"),
        "STAR": ("L4_ANALYZE", "L4 分析・★星號語序重組邏輯"),
        "READING": ("L4_ANALYZE", "L4 分析・篇章脈絡與多條件檢索"),
        "LISTENING": ("L3_APPLY", "L3 應用・聽解關鍵轉折與即時應答"),
    }

    full_bank = []

    # Pass 1: Official 100% Mock Exam Items (89 items, `inMock100: True`, `poolTier: "MOCK_100"`)
    for m_num, code, sec, cat, m_name, mock_cnt, pool_cnt, t_sec, instr in N4_MONDAI_SPECS:
        seeds = SEEDS_BY_MONDAI[m_num]
        assert len(seeds) == mock_cnt, f"Mondai {m_num} seed count {len(seeds)} != mock_cnt {mock_cnt}"
        b_lvl, b_lbl = bloom_map[cat]

        for i in range(mock_cnt):
            base = copy.deepcopy(seeds[i])
            item = {
                "id": f"N4-M{m_num:02d}-{i+1:02d}",
                "level": "N4",
                "section": sec,
                "category": cat,
                "officialCode": code,
                "officialName": m_name,
                "mondaiNum": m_num,
                "subtag": base["subtag"],
                "targetSec": t_sec,
                "irtA": round(1.25 + (m_num % 5) * 0.06, 2),
                "irtB": round(-1.2 + (i % 5) * 0.18, 2),
                "bloomLevel": base.get("bloomLevel", b_lvl),
                "bloomLabel": base.get("bloomLabel", b_lbl),
                "instruction": instr,
                "stem": inject_inline_ruby(base["stem"], cat),
                "furiganaHint": base["furiganaHint"],
                "socraticHint": base["socraticHint"],
                "l1TransferNote": base["l1TransferNote"],
                "grammarChain": base["grammarChain"],
                "ttsText": base["ttsText"],
                "options": base["options"],
                "correctIndex": base["correctIndex"],
                "blindOptions": bool(base.get("blindOptions", code == "L5_QUICK_RESP")),
                "translation": base["translation"],
                "coreRule": base["coreRule"],
                "optionExplanations": base["optionExplanations"],
                "inMock100": True,
                "poolTier": "MOCK_100",
            }
            if cat == "STAR":
                item["correctSequence"] = base["correctSequence"]
            if "situationSvg" in base:
                item["situationSvg"] = base["situationSvg"]
            if cat == "LISTENING":
                item["audioFile"] = base["audioFile"]
                item["dialogue"] = base["dialogue"]
            # Vary correctIndex position across Mock items for non-STAR items
            if i > 0 and cat != "STAR":
                item = rotate_options(item, i)
            full_bank.append(item)

    # Pass 2: Practice Pool Expansion (178 items, `inMock100: False`, `poolTier: "PRACTICE_300"`)
    for m_num, code, sec, cat, m_name, mock_cnt, pool_cnt, t_sec, instr in N4_MONDAI_SPECS:
        seeds = SEEDS_BY_MONDAI[m_num]
        practice_cnt = pool_cnt - mock_cnt
        b_lvl, b_lbl = bloom_map[cat]

        for i in range(practice_cnt):
            base = copy.deepcopy(seeds[i % len(seeds)])
            badge = CONTEXT_BADGES[(m_num + i) % len(CONTEXT_BADGES)]
            variant_round = (i // len(seeds)) + 1
            item = {
                "id": f"N4-P{m_num:02d}-{i+1:02d}",
                "level": "N4",
                "section": sec,
                "category": cat,
                "officialCode": code,
                "officialName": m_name,
                "mondaiNum": m_num,
                "subtag": f"{base['subtag']}・実戦演習#{variant_round} {badge}",
                "targetSec": t_sec,
                "irtA": round(1.30 + ((m_num + i) % 5) * 0.06, 2),
                "irtB": round(-1.1 + ((i % 7) - 2) * 0.15, 2),
                "bloomLevel": base.get("bloomLevel", b_lvl),
                "bloomLabel": base.get("bloomLabel", b_lbl),
                "instruction": instr,
                "stem": inject_inline_ruby(base["stem"], cat),
                "furiganaHint": base["furiganaHint"],
                "socraticHint": base["socraticHint"],
                "l1TransferNote": base["l1TransferNote"],
                "grammarChain": base["grammarChain"],
                "ttsText": base["ttsText"],
                "options": base["options"],
                "correctIndex": base["correctIndex"],
                "blindOptions": bool(base.get("blindOptions", code == "L5_QUICK_RESP")),
                "translation": base["translation"],
                "coreRule": base["coreRule"],
                "optionExplanations": base["optionExplanations"],
                "inMock100": False,
                "poolTier": "PRACTICE_300",
            }
            if cat == "STAR":
                item["correctSequence"] = base["correctSequence"]
            if "situationSvg" in base:
                item["situationSvg"] = base["situationSvg"]
            if cat == "LISTENING":
                item["audioFile"] = base["audioFile"]
                item["dialogue"] = base["dialogue"]
            if cat != "STAR":
                item = rotate_options(item, i + 1)
            full_bank.append(item)

    return full_bank


def verify_n4_bank(data: list[dict]):
    assert len(data) == 267, f"Expected 267 total items, got {len(data)}"
    mock_items = [q for q in data if q.get("inMock100") is True]
    assert len(mock_items) == 89, f"Expected 89 inMock100 items, got {len(mock_items)}"

    for m_num, code, sec, cat, m_name, mock_cnt, pool_cnt, _, _ in N4_MONDAI_SPECS:
        m_all = [q for q in data if q.get("mondaiNum") == m_num and q.get("officialCode") == code]
        m_mock = [q for q in m_all if q.get("inMock100") is True]
        assert len(m_all) == pool_cnt, f"Mondai {m_num} ({code}) total {len(m_all)} != {pool_cnt}"
        assert len(m_mock) == mock_cnt, f"Mondai {m_num} ({code}) mock {len(m_mock)} != {mock_cnt}"

    for q in data:
        if q.get("category") == "STAR":
            assert q["correctSequence"][2] == q["correctIndex"], f"STAR mismatch in {q['id']}"
        if q.get("officialCode") == "L4_UTTERANCE":
            assert "<svg" in q.get("situationSvg", ""), f"Missing situationSvg in {q['id']}"
        if q.get("officialCode") == "L5_QUICK_RESP":
            assert q.get("blindOptions") is True, f"blindOptions must be True in {q['id']}"

    unique_stems = len(set(q["stem"] for q in data))
    assert unique_stems >= 60, f"Expected >= 60 unique stems, got {unique_stems}"
    print(f"[PASS] N4 Bank Verified: Total={len(data)}, Mock100={len(mock_items)}, UniqueStems={unique_stems}")


def main():
    bank = build_n4_bank()
    verify_n4_bank(bank)
    out_path = DATA_DIR / "n4_bank.json"
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(bank, f, ensure_ascii=False, indent=2)
    print(f"[SAVED] {out_path} ({len(bank)} items)")


if __name__ == "__main__":
    main()
